// routing-curve: a polyline through the ends and middle of an arc, the middle raised 5 mm, with 2 mm bends
export function c009(context is Context, id is Id)
{
    const guide = newSketchOnPlane(context, id + "guide", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(guide, "a1", { "start" : vector(0, 0) * millimeter, "mid" : vector(14.142136, 5.857864) * millimeter, "end" : vector(20, 20) * millimeter });
    skSolve(guide);
    routingCurve(context, id + "route1", { "preselectedEntities" : qNothing(), "curveType" : RoutingCurveType.POLYLINE, "step" : CurveStep.POINTS, "inputType" : InputType.VERTEX, "inputVertices" : qNothing(), "isPeriodic" : false, "curveBaseCSys" : qNothing(), "pointsEditType" : PointsEditType.SINGLE, "pointIndex" : 0, "addPointOnAxisDrag" : false, "showCSys" : false, "keepPoints" : false, "curveLength" : 0 * millimeter, "bendRadius" : 2 * millimeter, "points" : [routingCurvePoint(0, qOwnedByBody(qBodyType(qCreatedBy(id + "guide", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), 0, vector(0, 0, 0) * millimeter), routingCurvePoint(1, qOwnedByBody(qBodyType(qCreatedBy(id + "guide", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), 0.5, vector(0, 0, 5) * millimeter), routingCurvePoint(2, qOwnedByBody(qBodyType(qCreatedBy(id + "guide", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), 1, vector(0, 0, 0) * millimeter)] });
}

// decal: an image on a block's top, realigned to a mate connector at a corner and the edge along y
export function c010(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 12 * millimeter });
    mateConnector(context, id + "mc1", { "originQuery" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(0, 0, 12) * millimeter), "entityInferenceType" : EntityInferenceType.POINT, "ownerPart" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) });
    decal(context, id + "decal1", { "image" : { "imageWidth" : 200, "imageHeight" : 100, "mediaType" : "image/png" } as ImageData, "face" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 12) * millimeter), "angle" : 0 * degree, "angleOppositeDirection" : false, "uShift" : 0 * millimeter, "vShift" : 0 * millimeter, "realign" : true, "originConnector" : qCreatedBy(id + "mc1", EntityType.BODY), "horizontalReference" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(0, 15, 12) * millimeter), "maintainAspectRatio" : true, "aspectRatioConstraint" : ImageAspectRatioConstraint.WIDTH_DRIVING, "width" : 20 * millimeter, "imageOriginIndex" : 4 });
    return { "decals" : decalNumbers(context, qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 12) * millimeter)) };
}

