// cutlist: a square tube along two top edges of a block and the rounded corner between, merged into one segment, and its table
export function c013(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, -10) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(60, 40) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    fillet(context, id + "round1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(60, 0, -5) * millimeter), "radius" : 10 * millimeter });
    frame(context, id + "frame1", { "profileSketch" : profileOf(squareTube), "selections" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(30, 0, 0) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(57.071068, 2.928932, 0) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(60, 25, 0) * millimeter)]), "mergeTangentSegments" : true });
    cutlist(context, id + "cutlist1", { "selectAllFrames" : false, "frames" : qBodyType(qCreatedBy(id + "frame1", EntityType.BODY), BodyType.SOLID) });
    return { "table" : caseTables(context, id, cutlistTable(context, {})) };
}

